def obj_value(obj, name, default=None):
    if isinstance(obj, dict):
        return obj.get(name, default)
    return getattr(obj, name, default)


def auth_session_from_response(response):
    data = obj_value(response, "session")
    if data is None:
        data = obj_value(response, "data", {})
        data = obj_value(data, "session")
    return data


def current_user():
    return st.session_state.get("user")


def current_uid():
    user = current_user()
    return obj_value(user, "id") if user else None


def save_session(response):
    session = auth_session_from_response(response)
    if not session:
        return False
    st.session_state["auth_session"] = session
    user = obj_value(session, "user")
    if user:
        st.session_state["user"] = user
    return True


def refresh_user_from_session():
    session = st.session_state.get("auth_session")
    if session:
        user = obj_value(session, "user")
        if user:
            st.session_state["user"] = user


def safe_email():
    user = current_user()
    return str(obj_value(user, "email", "") or "").lower().strip()


def sign_out():
    try:
        if sb:
            sb.auth.sign_out()
    except Exception:
        pass
    for key in ("user", "auth_session", "otp_email", "otp_mode", "google_waiting"):
        st.session_state.pop(key, None)
    st.rerun()


# -------------------- GOOGLE OAUTH CALLBACK --------------------
if sb:
    try:
        qp = st.query_params
        auth_code = qp.get("code")
        if auth_code and not st.session_state.get("user"):
            result = sb.auth.exchange_code_for_session(auth_code)
            if save_session(result):
                st.query_params.clear()
                st.success("Đăng nhập Google thành công.")
                st.rerun()
    except Exception as oauth_error:
        st.warning(f"Chưa hoàn tất đăng nhập Google: {oauth_error}")


