def fetch_profile(uid):
    if not admin_sb or not uid:
        return None
    try:
        r = admin_sb.table("profiles").select("*").eq("id", uid).maybe_single().execute()
        if r.data:
            return r.data
        # Backfill profile for accounts created before the SQL trigger was installed.
        admin_sb.table("profiles").upsert(
            {"id": uid, "email": safe_email(), "is_lifetime": False}
        ).execute()
        r = admin_sb.table("profiles").select("*").eq("id", uid).maybe_single().execute()
        return r.data
    except Exception:
        return None


def is_lifetime_member(uid):
    profile = fetch_profile(uid)
    return bool(profile and profile.get("is_lifetime"))


def create_payment_order(uid, email):
    if not admin_sb:
        raise RuntimeError("Thiếu Supabase service_role_key.")
    code = "BAP" + datetime.now().strftime("%y%m%d") + uuid.uuid4().hex[:6].upper()
    row = {
        "user_id": uid,
        "email": email,
        "amount": PLAN_PRICE,
        "order_code": code,
        "status": "pending",
    }
    result = admin_sb.table("payment_orders").insert(row).execute()
    return code


def user_orders(uid):
    if not admin_sb:
        return []
    try:
        r = (
            admin_sb.table("payment_orders")
            .select("order_code,amount,status,created_at")
            .eq("user_id", uid)
            .order("created_at", desc=True)
            .limit(20)
            .execute()
        )
        return r.data or []
    except Exception:
        return []


